create policy "cg drivers update own pending vehicle" on public.cg_vehicles for update to authenticated using (exists (select 1 from public.cg_driver_profiles d where d.id=public.cg_vehicles.driver_id and d.user_id=auth.uid() and d.status='pending')) with check (exists (select 1 from public.cg_driver_profiles d where d.id=public.cg_vehicles.driver_id and d.user_id=auth.uid() and d.status='pending'));